const item = $input.first().json;
const UMBRAL_CONFIANZA = 0.75;
const CATEGORIAS_ALTA = ['RECLAMO', 'RESERVA_HABITACION', 'RESPUESTA_RESERVA', 'EQUIPO_INTERNO', 'INFO_CLIENTE', 'PAGO'];

// Acepta tanto texto crudo (JSON.parse manual) como el objeto ya
// estructurado si viene del Structured Output Parser, y tolera que el
// modelo envuelva la respuesta en una clave extra como 'output'.
let raw = item.output;
if (raw && typeof raw === 'object') {
  raw = raw.output && typeof raw.output === 'object' ? raw.output : raw;
} else {
  raw = (raw || '').toString().replace(/```json|```/g, '').trim();
  try {
    const parsed = JSON.parse(raw);
    raw = (parsed.output && typeof parsed.output === 'object') ? parsed.output : parsed;
  } catch (e) {
    raw = null;
  }
}

let data = raw;
if (data && typeof data.importancia === 'string') {
  data = { ...data, importancia: data.importancia.toLowerCase() };
}
if (data && typeof data.categoria === 'string') {
  data = { ...data, categoria: data.categoria.toUpperCase() };
}

if (!data || !['alta', 'baja'].includes(data.importancia) ||
    (data.importancia === 'alta' && data.categoria && !CATEGORIAS_ALTA.includes(data.categoria))) {
  data = { importancia: 'alta', categoria: null, confianza: 0, motivo: 'Salida invalida del modelo, forzada a revision.' };
}

const n = Number(data.confianza);
const confianza = Number.isFinite(n) ? n : 0;

if (data.importancia === 'baja' && confianza < UMBRAL_CONFIANZA) {
  data.importancia = 'alta';
  data.categoria = data.categoria || 'REVISION_BAJA_CONFIANZA';
}

return [{
  json: {
    status: 'success',
    data: {
      importancia: data.importancia,
      categoria: data.categoria || null,
      confianza,
      umbral: UMBRAL_CONFIANZA,
      motivo: data.motivo || ''
    },
    meta: { worker: 'worker_triage_otros', model: 'gemini-agent' }
  }
}];

const err = $input.first().json;
return [{
  json: {
    status: 'error',
    data: {
      importancia: 'alta',
      categoria: 'FALLO_WORKER',
      confianza: 0,
      umbral: 0.75,
      motivo: 'No se pudo evaluar automaticamente: el Worker fallo.',
      reason: 'worker_call_failed',
      detail: (err.error && err.error.message) || err.message || 'Error desconocido al invocar el modelo'
    },
    meta: { worker: 'worker_triage_otros' }
  }
}];
